<script>
document.addEventListener('DOMContentLoaded',()=>{const list=document.getElementById('catalog-order');list.addEventListener('click',e=>{const row=e.target.closest('li');if(!row)return;if(e.target.closest('[data-order-up]')&&row.previousElementSibling)list.insertBefore(row,row.previousElementSibling);if(e.target.closest('[data-order-down]')&&row.nextElementSibling)list.insertBefore(row.nextElementSibling,row);if(e.target.closest('[data-order-remove]'))row.remove();});document.getElementById('append-game').addEventListener('click',()=>{const select=document.getElementById('add-game');if(!select.value||[...list.querySelectorAll('input')].some(i=>i.value===select.value))return;const row=document.createElement('li');row.className='list-group-item d-flex flex-wrap align-items-center gap-2';row.dataset.gameId=select.value;const input=document.createElement('input');input.type='hidden';input.name='game_ids[]';input.value=select.value;row.append(input);const label=document.createElement('span');label.className='me-auto';label.textContent=select.selectedOptions[0].textContent;row.append(label);for(const [attr,text]of [['data-order-up','↑'],['data-order-down','↓'],['data-order-remove',@js(__('admin_catalog.remove'))]]){const b=document.createElement('button');b.type='button';b.className='btn btn-sm btn-outline-secondary';b.setAttribute(attr,'');b.textContent=text;row.append(b);}list.append(row);});});
</script>
